async function Vb(r) {
  if (!r || !r.trim()) return "";
  if (/[\u0C00-\u0C7F]/.test(r)) return r.trim();
  try {
    const t = await (
      await fetch(
        `https://translate.googleapis.com/translate_a/single?client=gtx&sl=en&tl=te&dt=t&q=${encodeURIComponent(r.trim())}`,
      )
    ).json();
    if (Array.isArray(t) && Array.isArray(t[0]))
      return t[0].map((n) => n[0]).join("") || r;
  } catch (e) {
    console.warn("Translate to Telugu error:", e);
  }
  return r;
}
